//! Compares the Rust catalogue with output of the real Java `UniverseCatalog`
//! (seed 12345; generated by tests/Gold.java.txt against the compiled game).
use universe::{SystemId, UniverseCatalog};

#[test]
fn matches_java_golden() {
    let golden = include_str!("java_golden.txt");
    let mut cat = UniverseCatalog::new(12345);
    let mut checked = 0;
    let mut current: Option<universe::StarSystem> = None;
    let mut idx = 0;
    let mut expected_len = 0;
    for line in golden.lines().filter(|l| !l.is_empty()) {
        let line_owned = line.replace("Asteroid ", "Asteroid_");
        let f: Vec<&str> = line_owned.split(' ').collect();
        if f[0] == "S" {
            if current.is_some() { assert_eq!(idx, expected_len); }
            let id: Vec<i64> = f[1].split(',').map(|v| v.parse().unwrap()).collect();
            let s = cat.system(SystemId { x: id[0], y: id[1], z: id[2] }).clone();
            assert_eq!(s.seed, f[2].parse::<i64>().unwrap());
            assert_eq!(s.star_color, f[3].parse::<i32>().unwrap());
            expected_len = f[4].parse().unwrap();
            assert_eq!(s.bodies.len(), expected_len, "body count in {}", f[1]);
            current = Some(s);
            idx = 0;
            continue;
        }
        let p = &current.as_ref().unwrap().bodies[idx];
        idx += 1;
        let near = |a: f64, b: &str| {
            let b: f64 = b.parse().unwrap();
            assert!((a - b).abs() < 1e-6, "{} vs {} in {}", a, b, line);
        };
        assert_eq!(p.id.body as usize, f[0].parse::<usize>().unwrap());
        assert_eq!(p.name.replace(' ', "_"), f[1], "{line}");
        assert_eq!(p.seed, f[2].parse::<i64>().unwrap(), "{line}");
        assert_eq!(p.parent_body, f[3].parse::<i32>().unwrap(), "{line}");
        near(p.center.x, f[4]);
        near(p.center.y, f[5]);
        near(p.center.z, f[6]);
        near(p.radius, f[7]);
        near(p.environment.temperature, f[8]);
        assert_eq!(p.environment.sky_color, f[9].parse::<i32>().unwrap(), "{line}");
        assert_eq!(p.environment.ground_color, f[10].parse::<i32>().unwrap(), "{line}");
        checked += 1;
    }
    assert!(checked > 80, "checked {checked}");
}
